const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Rectangle([36.10, 36.15, 36.25, 36.25]); // Antakya, Hatay
  const date1 = '2023-02-21';
  const date2 = '2023-04-30';

  // 2. Data Acquisition & Filtering
  const collection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
    .select('avg_rad');

  // Since the collection is monthly, we find the image that contains each date.
  const image1 = collection.filterDate('2023-02-01', '2023-02-28').first();
  const image2 = collection.filterDate('2023-04-01', '2023-04-30').first();

  // Use a fallback daily collection if monthly is not available
  const image1_info = ee.Algorithms.If(
    image1,
    image1,
    ee.ImageCollection('NOAA/VIIRS/DNB/DAILY_V1').filterDate(date1).select('avg_rad').mean()
  );

  const image2_info = ee.Algorithms.If(
    image2,
    image2,
    ee.ImageCollection('NOAA/VIIRS/DNB/DAILY_V1').filterDate(date2).select('avg_rad').mean()
  );

  const final_image1 = ee.Image(image1_info);
  const final_image2 = ee.Image(image2_info);

  // Check if images are valid
  const img1_bands = final_image1.bandNames().size();
  const img2_bands = final_image2.bandNames().size();

  if (img1_bands.getInfo() === 0 || img2_bands.getInfo() === 0) {
      console.log(`Image found for Feb 2023: ${img1_bands.getInfo() > 0}`);
      console.log(`Image found for Apr 2023: ${img2_bands.getInfo() > 0}`);
      console.log('Could not find a valid image for one or both dates.');
      console.log('A');
      return;
  }

  // 3. Processing & Calculation
  const scale = 1000;
  const reducer = ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
  });

  const stats1 = final_image1.reduceRegion({
    reducer: reducer,
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const stats2 = final_image2.reduceRegion({
    reducer: reducer,
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const avg_rad1_raw = stats1.get('avg_rad_mean');
  const count1_raw = stats1.get('avg_rad_count');
  const avg_rad2_raw = stats2.get('avg_rad_mean');
  const count2_raw = stats2.get('avg_rad_count');

  // Asynchronously evaluate the results
  const [avg_rad1, count1, avg_rad2, count2] = await Promise.all([
      ee.Number(avg_rad1_raw).getInfo(),
      ee.Number(count1_raw).getInfo(),
      ee.Number(avg_rad2_raw).getInfo(),
      ee.Number(count2_raw).getInfo()
  ]);

  // 4. Validation
  if (count1 === 0 || count2 === 0) {
      console.log(`Valid pixels for Feb 2023: ${count1}`);
      console.log(`Valid pixels for Apr 2023: ${count2}`);
      console.log('No valid pixels found in the area of interest after processing.');
      console.log('C2');
      return;
  }

  if (avg_rad1 === null || avg_rad2 === null) {
      console.log(`February 2023 Radiance: ${avg_rad1}`);
      console.log(`April 2023 Radiance: ${avg_rad2}`);
      console.log('Calculation resulted in a null value.');
      console.log('C3');
      return;
  }

  // 5. Final Answer
  console.log(`Avg Nighttime Radiance (Feb 2023): ${avg_rad1.toFixed(2)} (Pixels: ${count1})`);
  console.log(`Avg Nighttime Radiance (Apr 2023): ${avg_rad2.toFixed(2)} (Pixels: ${count2})`);
  console.log(`The question asks if the light intensity was greater on Feb 21 than Apr 30.`);

  if (avg_rad1 > avg_rad2) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error('An error occurred during Earth Engine initialization or analysis.');
    console.error(e);
    console.log('D');
  }
}

initEE();
